import marshal
from flask import Flask, request

app = Flask(__name__)

@app.route('/unmarshal')
def unmarshal_data():
    '''
İsteğin içinden 'data' anahtarını kullanarak marşallenmiş veriyi al.
    Veriyi hex'ten byte'a çevirerek aç.
    Açılmış veriyi geri döndür.
    '''
    marshalled_hex_data = request.args.get('data')
    if not marshalled_hex_data:
        return "No 'data' parameter provided in the request.", 400

    try:
        marshalled_bytes = bytes.fromhex(marshalled_hex_data)
        unmarshalled_data = marshal.loads(marshalled_bytes)
        return str(unmarshalled_data)
    except ValueError as e:
        return f"Invalid hex data: {e}", 400
    except Exception as e:
        return f"Error unmarshalling data: {e}", 400

