def login():
    '''
احصل على "اسم المستخدم" و"الرمز" من جسم الطلب وتحقق مما إذا كانت مجموعة المستخدم/الرمز موجودة في قاعدة البيانات.
    @return: كائن JSON يحتوي على مفتاح "رسالة" يحتوي على رسالة حالة المصادقة:
    "تمت المصادقة بنجاح" أو "فشلت المصادقة" في حالة النجاح أو الفشل، على التوالي.
    '''
    data = request.get_json()
    username = data.get("username", "")
    token = data.get("token", "")

    user = User.query.filter_by(username=username, token=token).first()

    if user:
        return jsonify({"message": "تمت المصادقة بنجاح"})
    else:
        return jsonify({"message": "فشلت المصادقة"}), 401
```

