import io

class SSHStreamReader:
    '''
'n Wrapper rondom 'n bytestroom wat die lees van 'n vaste aantal bytes vanaf 'n verbinding na 'n bediener toelaat. | @param stroom: Die stroom om van te lees. | Lees 'n vaste aantal bytes vanaf die stroom. 
        @param num_bytes: Die aantal bytes om te lees. 
        @return: Die geleesde bytes. 
        @raise EOFError: In die geval waar minder as num_bytes bytes in die onderliggende bytestroom oorbly.
    '''

    def __init__(self, stream: io.RawIOBase):
        '''
        @param stream:  The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        Reads a fixed number of bytes from the stream.
        @param num_bytes:  The number of bytes to read.
        @return:    The read bytes.
        @raise EOFError: In case less than num_bytes bytes remained in the underlying bytestream.
        '''
        read_data = b''
        while len(read_data) < num_bytes:
            chunk = self._stream.read(num_bytes - len(read_data))
            if not chunk:  # End of stream reached
                raise EOFError(f"Expected to read {num_bytes} bytes, but only {len(read_data)} bytes were available.")
            read_data += chunk
        return read_data
