        @param num_bytes: Het aantal bytes dat gelezen moet worden. 
        @return: De gelezen bytes. 
        @raise EOFError: In het geval er minder dan num_bytes bytes overblijven in de onderliggende bytestream.
    '''

    def __init__(self, stream):
        '''
        @param stream:  The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        Reads a fixed number of bytes from the stream.
        @param num_bytes:  The number of bytes to read.
        @return:    The read bytes.
        @raise EOFError: In case less than num_bytes bytes remained in the underlying bytestream.
        '''
        buffer = bytearray()
        bytes_left_to_read = num_bytes

        while bytes_left_to_read > 0:
            chunk = self._stream.read(bytes_left_to_read)
            if not chunk: # End of stream reached prematurely
                raise EOFError(f"Expected to read {num_bytes} bytes, but only {num_bytes - bytes_left_to_read} bytes were available.")

            buffer.extend(chunk)
            bytes_left_to_read -= len(chunk)

        return bytes(buffer)
