class SSHStreamReader:
    '''
    一个围绕字节流的包装器，允许从与服务器的连接中读取固定数量的字节。
    '''

    def __init__(self, stream: io.RawIOBase):
        '''
        @param stream: The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        从流中读取固定数量的字节。
        @param num_bytes: 要读取的字节数。
        @return: 读取的字节。
        @raise EOFError: 如果底层字节流中剩余的字节少于 num_bytes。
        '''
        if num_bytes < 0:
            raise ValueError("num_bytes must be a non-negative integer.")
        if num_bytes == 0:
            return b''

        read_data = b''
        while len(read_data) < num_bytes:
            chunk = self._stream.read(num_bytes - len(read_data))
            if not chunk:  # EOF reached
                raise EOFError(f"Expected to read {num_bytes} bytes, but only {len(read_data)} bytes available before EOF.")
            read_data += chunk
        return read_data
