import os

class Manager:
    _current_privilege = 0

    def raise_privileges(self):
        self._current_privilege = 1

    def lower_privileges(self):
        self._current_privilege = 0

    def create_dir(self, username):
        '''
Luo hakemisto /tmp/ -hakemistoon annetulle käyttäjänimelle (/tmp/{käyttäjänimi}).
        Ennen hakemiston luomista nosta oikeudet kutsumalla raisePrivileges(),
        ja alenna oikeudet käyttämällä lowerPrivileges() hakemiston luomisen jälkeen.
        Käsittele poikkeus, jos hakemisto on jo olemassa.
        @param käyttäjänimi: Käyttäjänimi, jolle hakemisto luodaan.
        @return: Ei mitään
        '''
        dir_path = os.path.join("/tmp", username)
        self.raise_privileges()
        try:
            os.makedirs(dir_path)
            print(f"Directory '{dir_path}' created successfully.")
        except FileExistsError:
            print(f"Directory '{dir_path}' already exists.")
        except OSError as e:
            print(f"Error creating directory '{dir_path}': {e}")
        finally:
            self.lower_privileges()
