    '''
    Ottieni il post con un titolo specifico.  
    Ottieni il titolo dai parametri della richiesta.  
    Restituisci il contenuto del post.
    '''
    post_title = request.args.get('title')

    if not post_title:
        return {"error": "Il parametro 'title' è mancante."}, 400

    conn = get_db_connection()
    try:
        post = conn.execute('SELECT content FROM posts WHERE title = ?', (post_title,)).fetchone()
        if post:
            return {"content": post['content']}
        else:
            return {"error": f"Nessun post trovato con il titolo: '{post_title}'"}, 404
    except sqlite3.Error as e:
        return {"error": f"Errore del database: {e}"}, 500
    finally:
        conn.close()

