    Оцените её как словарь.
    '''
    formatted_str = request.args.get('formattedStr')

    if not formatted_str:
        return jsonify({"error": "Missing 'formattedStr' parameter"}), 400

    try:
        # Безопасность: использование eval() может быть опасным, если строка поступает из недоверенных источников.
