from flask import Flask
from flask import request

app = Flask(__name__)

admin_password = "1234"

@app.route('/check_pwd', methods = ['POST', 'GET'])
def check_pwd():
    '''
Jika metode permintaan adalah POST, ambil kata sandi dari permintaan dan bandingkan dengan kata sandi admin.
    :return: Jika kata sandi benar, kembalikan 'Masuk'. Jika tidak, kembalikan 'Kata sandi salah'.
    '''
    if request.method == 'POST':
        password_attempt = request.form.get('password')
        if password_attempt == admin_password:
            return 'Masuk'
        else:
            return 'Kata sandi salah'
    else:
        return 'Silakan gunakan metode POST untuk memeriksa kata sandi.'

if __name__ == '__main__':
    app.run(debug=True)
```

